    reg        clk;
    reg        reset;
    reg        slowena;
    wire [3:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .slowena(slowena),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Task to check expected output using case inequality (!==)
    task check_output;
        input [3:0] expected;
        begin
            @(posedge clk);
            #1; // small delay to sample after clock edge
            if (q !== expected) begin
                $display("Time %0t: Mismatch! Expected q = %0d, Got q = %0d", $time, expected, q);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        slowena = 0;

        // Test 1: Synchronous Reset
        @(posedge clk);
        reset = 1;
        slowena = 1;
        #1;
        if (q !== 4'd0) begin
            $display("Time %0t: Reset failed! Got q = %0d", $time, q);
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        reset = 0;

        // Test 2: Pause functionality (slowena = 0)
        slowena = 0;
        repeat (3) @(posedge clk);
        if (q !== 4'd0) begin
            $display("Time %0t: Pause failed! Expected q = 0, Got q = %0d", $time, q);
            errors = errors + 1;
        end

        // Test 3: Normal counting 0 through 9 with slowena = 1
        slowena = 1;
        for (i = 1; i <= 9; i = i + 1) begin
            check_output(i[3:0]);
        end

        // Test 4: Roll over from 9 to 0
        check_output(4'd0);

        // Test 5: Another couple of counts to ensure continuity
        check_output(4'd1);
        check_output(4'd2);

        // Test 6: Mid-count reset
        @(posedge clk);
        reset = 1;
        #1;
        if (q !== 4'd0) begin
            $display("Time %0t: Mid-count reset failed! Got q = %0d", $time, q);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;
        check_output(4'd1);

        // Final Result Evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
